package app

// This fixture is generated by real handlers, never by either client fake.
// The injected stores contain synthetic domain data; no home/tmux is consulted.
import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"io"
	"net/http/httptest"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"

	"github.com/chenchaoyi/gtmux/internal/artifact"
	"github.com/chenchaoyi/gtmux/internal/hqworkspace"
	"github.com/chenchaoyi/gtmux/internal/server"
	"github.com/chenchaoyi/gtmux/internal/state"
)

type contractReader struct{ *bytes.Reader }

func (contractReader) Close() error { return nil }

func TestClientHTTPContracts(t *testing.T) {
	t.Setenv("HOME", t.TempDir())
	const file = "../../tests/contracts/http-contract.json"
	b, err := os.ReadFile(file)
	if err != nil {
		t.Fatal(err)
	}
	var contract struct {
		Schema int `json:"schema"`
		Seed   struct {
			Pane      string          `json:"pane"`
			Session   string          `json:"session"`
			Home      string          `json:"home"`
			Turns     json.RawMessage `json:"turns"`
			History   json.RawMessage `json:"history"`
			Workspace json.RawMessage `json:"workspace"`
			Document  struct {
				Reference string `json:"reference"`
				Body      string `json:"body"`
				ID        string `json:"id"`
				Kind      string `json:"kind"`
				Media     string `json:"media"`
			} `json:"document"`
		} `json:"seed"`
		Cases []struct {
			Capability string            `json:"capability,omitempty"`
			Name       string            `json:"name"`
			Path       string            `json:"path"`
			Method     string            `json:"method"`
			Role       string            `json:"role"`
			Body       json.RawMessage   `json:"body,omitempty"`
			Headers    map[string]string `json:"headers,omitempty"`
			Expected   any               `json:"expected,omitempty"`
		} `json:"cases"`
	}
	if err := json.Unmarshal(b, &contract); err != nil {
		t.Fatal(err)
	}
	seed := contract.Seed
	doc := seed.Document
	sum := sha256.Sum256([]byte(doc.Body))
	meta := artifact.File{ID: doc.ID, Name: "report.md", Source: doc.Reference, Kind: doc.Kind, MediaType: doc.Media, Bytes: int64(len(doc.Body)), SHA256: hex.EncodeToString(sum[:]), CreatedAt: 1700000000, SessionID: seed.Session, HomeID: seed.Home}
	var stored struct {
		Matters  []hqworkspace.Matter `json:"matters"`
		Revision uint64               `json:"revision"`
	}
	if err := json.Unmarshal(seed.Workspace, &stored); err != nil {
		t.Fatal(err)
	}
	database := hqworkspace.Empty()
	database.Revision = stored.Revision
	for _, m := range stored.Matters {
		database.Matters[m.ID] = m
	}
	dir := filepath.Join(state.HQHome(), "workspace")
	if err := os.MkdirAll(dir, 0700); err != nil {
		t.Fatal(err)
	}
	encodedDB, _ := json.Marshal(database)
	if err := os.WriteFile(filepath.Join(dir, "records.json"), encodedDB, 0600); err != nil {
		t.Fatal(err)
	}
	enroll := server.NewEnrollManager(nil, nil)
	guest := enroll.MintGuest("contract reader", []string{seed.Pane}, nil, 0)
	deps := server.Deps{Enroll: enroll,
		Transcript: func(id string, _ int) ([]byte, server.TranscriptMeta, error) {
			if id != seed.Pane {
				return []byte(`[]`), server.TranscriptMeta{}, nil
			}
			return seed.Turns, server.TranscriptMeta{Etag: `W/"contract-1"`, Dropped: 150, History: func(_ context.Context, before string) ([]byte, server.TranscriptMeta, error) {
				if before != "before-151" {
					return nil, server.TranscriptMeta{}, errors.New("stale")
				}
				return seed.History, server.TranscriptMeta{}, nil
			}}, nil
		},
		HQWorkspace: workspaceHTTPRead,
		ArtifactResolve: func(ref, sid, home string) (artifact.File, error) {
			if ref != doc.Reference || sid != seed.Session || home != seed.Home {
				return artifact.File{}, errors.New("unavailable")
			}
			return meta, nil
		},
		ArtifactContent: func(id, sid, home string) (artifact.File, io.ReadSeekCloser, error) {
			if id != doc.ID || sid != seed.Session || home != seed.Home {
				return artifact.File{}, nil, errors.New("unavailable")
			}
			return meta, contractReader{bytes.NewReader([]byte(doc.Body))}, nil
		},
	}
	srv := server.New(server.Config{Token: "contract-owner"}, deps)
	handler := srv.Handler()
	update := os.Getenv("GTMUX_UPDATE_HTTP_CONTRACT") == "1"
	for i, tc := range contract.Cases {
		t.Run(tc.Name, func(t *testing.T) {
			r := httptest.NewRequest(tc.Method, tc.Path, bytes.NewReader(tc.Body))
			if tc.Role != "unauthenticated" {
				token := "contract-owner"
				if tc.Role == "invalid" {
					token = "invalid-synthetic-token"
				}
				if tc.Role == "guest" {
					token = guest.Token
				}
				r.Header.Set("Authorization", "Bearer "+token)
			}
			for key, value := range tc.Headers {
				r.Header.Set(key, value)
			}
			w := httptest.NewRecorder()
			caseHandler := handler
			if tc.Capability == "no-workspace" {
				without := deps
				without.HQWorkspace = nil
				caseHandler = server.New(server.Config{Token: "contract-owner"}, without).Handler()
			}
			caseHandler.ServeHTTP(w, r)
			if w.Code >= 500 && !(tc.Capability == "no-workspace" && w.Code == 501) {
				t.Fatalf("unexpected server failure: %s", w.Body.String())
			}
			headers := map[string]string{}
			for _, key := range []string{"Content-Type", "Cache-Control", "ETag", "Allow", "X-Gtmux-Turns-Dropped", "X-Gtmux-History-Page", "Content-Disposition", "Content-Security-Policy", "X-Content-Type-Options", "X-Gtmux-SHA256"} {
				if value := w.Header().Get(key); value != "" {
					headers[strings.ToLower(key)] = value
				}
			}
			var body any
			if w.Body.Len() > 0 {
				if strings.Contains(w.Header().Get("Content-Type"), "application/json") {
					if err := json.Unmarshal(w.Body.Bytes(), &body); err != nil {
						t.Fatal(err)
					}
				} else {
					body = w.Body.String()
				}
			}
			// Only the two volatile overview clocks are normalized. All projection fields
			// and optional/empty values still come from production workspaceHTTPRead.
			if payload, ok := body.(map[string]any); ok {
				if overview, ok := payload["overview"].(map[string]any); ok {
					overview["generated_at"] = float64(1700000000)
					overview["since"] = float64(1699913600)
				}
			}
			actual := map[string]any{"status": float64(w.Code), "headers": headers, "body": body}
			// JSON-normalize maps so numeric types and header maps compare identically.
			encoded, _ := json.Marshal(actual)
			var normalized any
			_ = json.Unmarshal(encoded, &normalized)
			if update {
				contract.Cases[i].Expected = normalized
				return
			}
			if !reflect.DeepEqual(normalized, tc.Expected) {
				t.Errorf("real handler contract changed: got %s; review before updating golden", encoded)
			}
		})
	}
	if update && !t.Failed() {
		encoded, err := json.MarshalIndent(contract, "", "  ")
		if err != nil {
			t.Fatal(err)
		}
		if err = os.WriteFile(file, append(encoded, '\n'), 0644); err != nil {
			t.Fatal(err)
		}
	}
}
